INSERT INTO zinas (virsraksts, teksts, izveidots, publicets) VALUES
('Laipni lūdzam!', 'Laipni lūdzam iepazīties ar manu vietni! Šeit atradīsiet manis veidotās mājaslapas un skolas projektus.\n\nNupat esmu ieguvis programmatūras izstrādātāja kvalifikāciju — 2026. gada 1. oktobrī absolvēju Vamia profesionālo skolu Vāsā, Somijā. Šobrīd strādāju par mediju instruktoru Heinolas bibliotēkā, taču ar atvērtu sirdi raugos pretī jauniem vējiem — kas zina, varbūt tie aizpūtīs mani pat līdz Latvijai.\n\nOktobris iesācies lietains. Taču, kad kamīnā pielieku malku, lietu vairs nemanu. Joga māca, ka miers nav atkarīgs no tā, kas notiek ap mums, bet gan no tā, kā mēs uz to raugāmies — santoša, apmierinātība ar šo mirkli tādu, kāds tas ir. Iekurtā uguns atgādina par iekšējo siltumu, ko ikviens nesam sevī neatkarīgi no laikapstākļiem.\n\nUn viss plūst, viss mainās. Lietus pāries, un jau pēc astoņiem mēnešiem ārā atkal būs silts. Tāda ir pārmaiņu daba — nekas nepaliek nemainīgs, tāpēc nav vērts pārāk pieķerties ne grūtajam, ne vieglajam. Es cenšos domāt gaiši un elpot dziļi: arī šī pelēkā lietus diena ir dāvana.\n\nPriecāšos, ja uzkavēsieties un apskatīsiet manus darbus. Lai jums gaišas domas un silta sirds!', NOW(), 1);
